#include <iostream>
#include <vector>
#include <stack>
using namespace std;

class Graph {
private:
    vector<vector<int>> adj;
    int V;

public:
    Graph(int v) {
        V = v;
        adj.resize(v);
    }

    void addEdge(int u, int v) {
        adj[u].push_back(v);
        adj[v].push_back(u); // remove for directed graph
    }

    void dfsIterative(int start) {
        vector<bool> visited(V, false);
        stack<int> st;

        st.push(start);

        while (!st.empty()) {
            int node = st.top();
            st.pop();   // LIFO — last in, first out

            if (!visited[node]) {
                visited[node] = true;
                cout << node << " ";

                for (int neighbour : adj[node]) {
                    if (!visited[neighbour]) {
                        st.push(neighbour);
                    }
                }
            }
        }
    }
};

int main() {
    Graph g(8);

    g.addEdge(1,2);
    g.addEdge(1,3);
    g.addEdge(2,4);
    g.addEdge(4,5);
    g.addEdge(3,6);
    g.addEdge(6,7);

    g.dfsIterative(1);

    return 0;
}
